select set_config('tests.third',reda_publish_reviewed(tests.id(950000),tests.id(950451),reda_dashboard_patient(tests.id(950000))->>'token',(current_setting('tests.second')::jsonb->>'plan_id')::uuid,tests.plan(12),'Reviewed the next step','Your next reviewed step',null,(current_setting('tests.handover_decision')::jsonb->>'id')::uuid)::text,false);
select tests.ok(current_setting('tests.third')::jsonb->>'frame_continued'='true','exact approved next step retains remaining reviewed pathway');
